templates.template:
.dataList-subRow
{
	max-height: 100%;
}

.filterBlock--noFloat
{
	float: none;
}

.block
{
	&[data-content-type="user"]
	{
		.message-cell--extra
		{
			.m-fixedWidthFlex(240 + 2 * (@xf-messagePadding));
		}
	}
}

.multi-account-list
{
	&.dataList
	{
		font-size:90%;
	}

	& .dataList-cell
	{
		vertical-align:top;
	}
}

.multiple-account-block-body-inline
{
	display: flex;
	flex-direction: row;
	flex-wrap: wrap;
	align-items: stretch;
}

.multiple-account-block-row-inline
{
	border-right: @xf-borderSize solid @xf-borderColor;
	border-bottom: @xf-borderSize solid @xf-borderColor;
	display: inline-block;
	width: 33.3%;
	min-width: 320px;
	margin: 0;
	.m-clearFix();

	&.block-row--alt
	{
		.xf-contentAltBase();
	}

	&.block-row--minor
	{
		font-size: @xf-fontSizeSmall;
	}

	&.block-row--separated
	{
		padding-top: (@xf-blockPaddingV) * 2;
		padding-bottom: (@xf-blockPaddingV) * 2;

		+ .block-row
		{
			border-top: @xf-borderSize solid @xf-borderColorLight;
		}
	}
}

.multiple-account-block-filter
{
	display: inline-block;
	vertical-align: top;
}
